parameters.jsCode:
const i = $input.first().json;

const table = 'forest_incidents';

const lat =
  i.lat_validada ??
  i.lat ??
  i.coordenadas?.lat ??
  i.classification?.coordenadas?.lat ??
  null;

const lon =
  i.lon_validada ??
  i.lon ??
  i.coordenadas?.lon ??
  i.classification?.coordenadas?.lon ??
  null;

const payload = {
  incident_type: i.tipo || 'INCENDIO',
  description: i.descripcion || i.message || null,
  priority: i.prioridad || 'ALTA',
  reporter_name: i.userName || null,
  reporter_phone: i.from || null,
  latitude: lat,
  longitude: lon,
  parcela: i.parcela || null,
  case_id: i.caseId || null,
  status: i.necesita_coordenadas ? 'PENDIENTE_UBICACION' : 'ABIERTO',
  ai_classification: i.tipo || 'INCENDIO',
  assigned_to: 'Supervisor Forestal',
  location: lat !== null && lon !== null
    ? `SRID=4326;POINT(${lon} ${lat})`
    : null,
  metadata: {
    mensaje_original: i.message || null,
    subtipo:
  i.subtipo && i.subtipo !== 'null'
    ? i.subtipo
    : i.classification?.subtipo && i.classification.subtipo !== 'null'
      ? i.classification.subtipo
      : null,
    ubicacion_texto: i.ubicacion_texto || null,
    ubicacion_nombre: i.ubicacion_nombre || null,
    ubicacion_completa: i.ubicacion_completa || null,
    ubicacion_municipio: i.ubicacion_municipio || null,
    ubicacion_provincia: i.ubicacion_provincia || null,
    media_id: i.mediaId || null,
    media_type: i.mediaType || null,
    caption: i.caption || null,
original_message_type:
  i.isImage
    ? 'image'
    : i.hasNativeLocation
      ? 'location'
      : 'text',
    parcela: i.parcela || null,
    requiere_escalado: i.requiereEscalado ?? false, // FIX: default conservador, antes era 'true' y generaba falsos escalados al supervisor cuando requiereEscalado venia undefined
    channel: i.channel || 'whatsapp',
    conversation_id: i.conversationId || null,
    timestamp: i.timestamp || new Date().toISOString()
  }
};

// Eliminar campos principales null o undefined
Object.keys(payload).forEach(key => {
  if (payload[key] === null || payload[key] === undefined) {
    delete payload[key];
  }
});

// Limpiar metadata
Object.keys(payload.metadata).forEach(key => {
  if (payload.metadata[key] === null || payload.metadata[key] === undefined) {
    delete payload.metadata[key];
  }
});

return [{
  json: {
    table,
    payload,
    original: {
      ...i,
      lat,
      lon,
      ubicacion_nombre: i.ubicacion_nombre,
      ubicacion_completa: i.ubicacion_completa,
      ubicacion_municipio: i.ubicacion_municipio,
      ubicacion_provincia: i.ubicacion_provincia
    },
    _original_passthrough: {
      ...i,
      lat,
      lon,
      ubicacion_nombre: i.ubicacion_nombre,
      ubicacion_completa: i.ubicacion_completa,
      ubicacion_municipio: i.ubicacion_municipio,
      ubicacion_provincia: i.ubicacion_provincia
    }
  }
}];

const input = $input.first().json;

const original = $('Preparar Registro').first().json.original || {};

const finalMessage = `🔥 *Aviso de incendio forestal*

Necesito la ubicación exacta para registrar el incidente y activar el seguimiento.

Puedes enviarme:

📍 Tu ubicación de WhatsApp
🌍 Coordenadas (ej: 40.4168, -3.7038)
🗺️ Nombre del monte, paraje o zona

Responderé automáticamente cuando reciba la ubicación.`;

return [{
  json: {
    ...original,
    ...input,

    finalMessage,
    waitingForCoords: true,

    whatsappTo: String(original.from || '').replace(/\D/g, ''),
    whatsappText: finalMessage
  }
}];

const saved = $input.first().json;
const metadata = saved.metadata || {};

let original = saved.original || saved._original_passthrough || null;
if (!original) {
  try {
    original = $('Preparar Registro').first().json.original || {};
  } catch (e) {
    original = {};
  }
}

const from = original.from || saved.reporter_phone || metadata.telefono || '';
const userName = original.userName || saved.reporter_name || metadata.responsable || 'Usuario';
const tipo = original.tipo || saved.incident_type || metadata.tipo || 'No especificado';
const prioridad = original.prioridad || saved.priority || metadata.prioridad || 'No especificada';
const caseId = original.caseId || saved.case_id || metadata.case_id || 'No disponible';
const descripcion = original.descripcion || saved.description || metadata.descripcion || 'Sin descripción';
const lat = original.lat || saved.latitude || metadata.coordenadas_lat || null;
const lon = original.lon || saved.longitude || metadata.coordenadas_lon || null;
const requiereEscalado = original.requiereEscalado || metadata.requiere_escalado || false;
const finalMessage = original.finalMessage || 'Incidente registrado correctamente.';

// La ubicación viene DIRECTAMENTE de original
const ubicacionNombre = original.ubicacion_nombre || null;
const ubicacionLegible = ubicacionNombre || (lat && lon ? `${lat}, ${lon}` : 'Sin coordenadas');
const supervisorNumber = $env.SUPERVISOR_WHATSAPP || '';

// Mensaje para el USUARIO (con ID y ubicación)
const userMessage = `${finalMessage}\n\n📋 ID de registro: ${caseId}\n\n📍 *Ubicación:* ${ubicacionLegible}\n\n🌲 Gracias por proteger nuestros bosques.`;

// Mensaje para el SUPERVISOR (con ID y ubicación legible)
const supervisorMessage = `🌲 *WILDFIRE SENTINEL AI*\n━━━━━━━━━━━━━━━━━━━━\n📌 *NUEVO CASO*\n━━━━━━━━━━━━━━━━━━━━\n🔹 *Tipo:* ${tipo}\n🔹 *Prioridad:* ${prioridad}\n🔹 *ID:* ${caseId}\n🔹 *Ubicación:* ${ubicacionLegible}\n🔹 *Reporta:* ${userName}\n🔹 *Teléfono:* ${from}\n━━━━━━━━━━━━━━━━━━━━\n📝 *Descripción:*\n${descripcion}\n━━━━━━━━━━━━━━━━━━━━\n⚠️ Se requiere atención inmediata.`;

return [{
  json: {
    from: from,
    reporter_phone: from,
    userName: userName,
    tipo: tipo,
    prioridad: prioridad,
    caseId: caseId,
    descripcion: descripcion,
    finalMessage: finalMessage,
    requiereEscalado: requiereEscalado,
    lat: lat,
    lon: lon,
    supabaseResponse: saved,
    supervisorNumber: supervisorNumber,
    supervisorMessage: supervisorMessage,
    shouldNotifySupervisor:
  (tipo === 'INCENDIO' && prioridad !== 'BAJA') || prioridad === 'ALTA',
    userMessage: userMessage,
    // Añadir ubicación para el siguiente nodo
    ubicacion_nombre: ubicacionNombre
  }
}];

const i = $input.first().json;

const caseId =
  i.caseId ||
  i.pending_state?.pending_case_id ||
  i.pending_case_id ||
  'No disponible';

const lat = i.lat_validada;
const lon = i.lon_validada;

const ubicacion =
  i.ubicacion_nombre ||
  i.ubicacion_completa ||
  `${lat}, ${lon}`;

const ubicacionCompleta = i.ubicacion_completa
  ? `\n📌 Dirección aprox.: ${i.ubicacion_completa}`
  : '';

const message = `✅ Caso completado con coordenadas.

📋 ID de registro: ${caseId}
📍 Ubicación: ${ubicacion}${ubicacionCompleta}
🧭 Coordenadas: ${lat}, ${lon}

🌲 Gracias por proteger nuestros bosques.`;

return [{
  json: {
    ...i,
    whatsappTo: String(i.from || '').replace(/\D/g, ''),
    whatsappText: message,
    finalMessage: message,
    userMessage: message,
    caso_completado: true,
    caseId
  }
}];

