const inputData = $input.first().json;

// 1. Teléfono
let phoneNumber =
  inputData.whatsappTo ||
  inputData.reporter_phone ||
  inputData.from ||
  inputData.telefono ||
  inputData.metadata?.telefono ||
  inputData.original?.from ||
  inputData.supabaseResponse?.reporter_phone ||
  null;

// 2. Case ID
const caseId =
  inputData.caseId ||
  inputData.case_id ||
  inputData.metadata?.case_id ||
  inputData.supabaseResponse?.case_id ||
  inputData.supabaseResponse?.id ||
  null;

// 3. Coordenadas
const lat =
  inputData.lat_validada ??
  inputData.lat ??
  inputData.latitude ??
  inputData.supabaseResponse?.latitude ??
  null;

const lon =
  inputData.lon_validada ??
  inputData.lon ??
  inputData.longitude ??
  inputData.supabaseResponse?.longitude ??
  null;

// 4. Ubicación legible
const ubicacion =
  inputData.ubicacion_nombre ||
  inputData.ubicacion_municipio ||
  inputData.ubicacion_provincia ||
  inputData.ubicacion_completa ||
  (lat && lon ? `${lat}, ${lon}` : 'Sin coordenadas');

const direccionAprox = inputData.ubicacion_completa
  ? `\n📌 Dirección aprox.: ${inputData.ubicacion_completa}`
  : '';

const coordenadasTexto = lat && lon
  ? `\n🧭 Coordenadas: ${lat}, ${lon}`
  : '';

// 5. Detectar si es mensaje casual sin caso
const esSinCaso =
  inputData.crearCaso === false ||
  inputData.caseId === null ||
  inputData.tipo === 'OTRO' && !caseId;

// 6. Construir mensaje
let messageText;

if (esSinCaso) {
  messageText =
    inputData.userMessage ||
    inputData.finalMessage ||
    inputData.classification?.respuesta_usuario ||
    '¿Quieres reportar humo, fuego o una posible situación de riesgo de incendio forestal?';
} else {
  const intro =
    inputData.finalMessage ||
    inputData.userMessage ||
    'Caso registrado correctamente.';

  messageText = `${intro}

📋 ID de registro: ${caseId || 'No disponible'}
📍 Ubicación: ${ubicacion}${direccionAprox}${coordenadasTexto}

🌲 Gracias por proteger nuestros bosques.`;
}

// 7. Fallback teléfono
if (!phoneNumber) {
  const str = JSON.stringify(inputData);
  const match = str.match(/34\d{9}/);
  phoneNumber = match ? match[0] : null;
}

if (!phoneNumber) {
  return [{
    json: {
      ...inputData,
      whatsappSkipped: true,
      skipReason: 'No phone number',
      whatsappTo: '',
      whatsappText: messageText
    }
  }];
}

const cleanPhone = String(phoneNumber).replace(/\D/g, '');

return [{
  json: {
    ...inputData,
    whatsappSkipped: false,
    whatsappTo: cleanPhone,
    whatsappText: messageText,
    userMessage: messageText,
    finalMessage: messageText
  }
}];

