const i = $('Validar Coordenadas').first().json;
const geoResponse = $input.first().json;

let ubicacionNombre = null;
let ubicacionCompleta = null;
let municipio = null;
let provincia = null;

if (geoResponse.status === "OK" && geoResponse.results && geoResponse.results.length > 0) {
  const firstResult = geoResponse.results[0];
  ubicacionCompleta = firstResult.formatted_address;

  // Extraer componentes de dirección
  for (const component of firstResult.address_components) {
    if (component.types.includes("locality")) {
      municipio = component.long_name;
    }
    if (component.types.includes("administrative_area_level_1")) {
      provincia = component.long_name;
    }
  }

  // Definir nombre a mostrar
  if (municipio) {
    ubicacionNombre = municipio;
  } else if (provincia) {
    ubicacionNombre = provincia;
  } else {
    ubicacionNombre = ubicacionCompleta.split(',')[0];
  }

  // Si hay parcela, priorizarla
  if (i.parcela) {
    ubicacionNombre = `Parcela ${i.parcela} (${municipio || provincia || 'Ubicación detectada'})`;
  }
} else {
  // Fallback: usar coordenadas
  ubicacionNombre = `${i.lat_validada}, ${i.lon_validada}`;
  ubicacionCompleta = null;
}

return [{
  json: {
    ...i,
    ubicacion_nombre: ubicacionNombre,
    ubicacion_completa: ubicacionCompleta,
    ubicacion_municipio: municipio,
    ubicacion_provincia: provincia,
    geocoding_status: geoResponse.status
  }
}];

const input = $input.first().json;
const body = input.body || input;

const value = body.entry?.[0]?.changes?.[0]?.value;

if (value?.statuses && !value?.messages) return [];

const msg = value?.messages?.[0];
const contact = value?.contacts?.[0];

if (!msg) return [];

let message = '';
let mediaId = '';
let mediaType = '';
let latitude = null;
let longitude = null;
let caption = '';

if (msg.type === 'text') {
  message = msg.text?.body || '';

} else if (msg.type === 'location') {
  latitude = msg.location?.latitude ?? null;
  longitude = msg.location?.longitude ?? null;
  mediaType = 'location';
  message = `ubicacion: ${latitude}, ${longitude}`;

} else if (msg.type === 'image') {
  mediaId = msg.image?.id || '';
  mediaType = 'image';
  caption = msg.image?.caption || '';
  message = caption || '[imagen recibida]';

} else if (msg.type === 'document') {
  mediaId = msg.document?.id || '';
  mediaType = 'document';
  caption = msg.document?.caption || '';
  message = caption || msg.document?.filename || '[documento recibido]';

} else if (msg.type === 'interactive') {
  message =
    msg.interactive?.button_reply?.title ||
    msg.interactive?.button_reply?.id ||
    msg.interactive?.list_reply?.title ||
    msg.interactive?.list_reply?.id ||
    '';

} else {
  mediaType = msg.type || 'archivo';
  message = `[${msg.type || 'archivo'} recibido]`;
}

const from = String(msg.from || '').replace(/\D/g, '');
const userName = contact?.profile?.name || 'Usuario Forestal';
const conversationId = `whatsapp:${from}`;
const incomingMessageId =
  msg.id ||
  `${conversationId}:${message}:${Math.floor(Date.now() / 5000)}`;

try {
  const staticData = $getWorkflowStaticData('global');
  staticData.processedMessages = staticData.processedMessages || {};

  if (staticData.processedMessages[incomingMessageId]) return [];

  staticData.processedMessages[incomingMessageId] = new Date().toISOString();

  const ids = Object.keys(staticData.processedMessages);
  if (ids.length > 1000) {
    for (const id of ids.slice(0, ids.length - 1000)) {
      delete staticData.processedMessages[id];
    }
  }
} catch (e) {}

if (!message || !from) return [];

return [{
  json: {
    channel: 'whatsapp',
    from,
    userName,
    message: String(message).trim(),
    caption: String(caption || '').trim(),

    conversationId,
    incomingMessageId,

    mediaId,
    mediaType,

    isImage: mediaType === 'image',
    hasMedia: !!mediaId,
    hasNativeLocation: latitude !== null && longitude !== null,
    hasText: !!String(message || '').trim() && message !== '[imagen recibida]',

    latitude,
    longitude,

    timestamp: new Date().toISOString(),
    raw: body
  }
}];

const original = $('Rate Limiter').first().json;
const rows = $input.all().map(item => item.json);

const row = rows.find(r => r.pending_case_id);

return [{
  json: {
    ...original,

    has_pending: !!row,

    caseId: row?.pending_case_id || null,
    pending_case_id: row?.pending_case_id || null,
    pending_type: row?.pending_type || null,
    pending_priority: row?.pending_priority || null,

    is_pending_coords_message:
      !!row &&
      (
        original.latitude !== null ||
        /-?\d+(\.\d+)?[, ]+-?\d+(\.\d+)?/.test(original.message)
      )
  }
}];

const input = $input.first().json;
const now = Date.now();
const WINDOW_MS = 60000;
const MAX_MESSAGES = Number($env.RATE_LIMIT_PER_MINUTE || 15);
try {
  const staticData = $getWorkflowStaticData('global');
  staticData.rateLimiter = staticData.rateLimiter || {};
  const key = `rate:${input.conversationId}`;
  const item = staticData.rateLimiter[key] || { timestamps: [] };
  item.timestamps = (item.timestamps || []).filter(t => now - t < WINDOW_MS);
  if (item.timestamps.length >= MAX_MESSAGES) {
    staticData.rateLimiter[key] = item;
    return [{json:{...input, rateLimited:true, finalMessage:'Estoy recibiendo muchos mensajes seguidos. Espera unos segundos y vuelve a intentarlo, por favor.'}}];
  }
  item.timestamps.push(now);
  staticData.rateLimiter[key] = item;
} catch(e) {}
return [{json:{...input, rateLimited:false}}];

const i = $input.first().json;
const texto = String(i.message || '').trim();

// Si llega ubicacion nativa de WhatsApp, tiene prioridad sobre el texto
if (i.latitude !== null && i.latitude !== undefined && i.longitude !== null && i.longitude !== undefined) {
  return [{
    json: {
      ...i,
      location_input_type: 'coords',
      lat_validada: i.latitude,
      lon_validada: i.longitude,
      coords_validas: true,
      caseId: i.caseId || i.pending_case_id,
      tipo: i.pending_type || 'INCENDIO',
      prioridad: i.pending_priority || 'MEDIA'
    }
  }];
}

const coordMatch = texto.match(/(-?\d+(?:\.\d+)?)\s*,\s*(-?\d+(?:\.\d+)?)/);

if (coordMatch) {
  const lat = parseFloat(coordMatch[1]);
  const lon = parseFloat(coordMatch[2]);

  // Validar rango coordenadas
  if (Number.isNaN(lat) || Number.isNaN(lon) || Math.abs(lat) > 90 || Math.abs(lon) > 180) {
    return [{
      json: {
        ...i,
        location_input_type: 'invalid',
        coords_validas: false,
        whatsappTo: String(i.from || '').replace(/\D/g, ''),
        whatsappText: 'Las coordenadas no parecen válidas. La latitud debe estar entre -90 y 90, y la longitud entre -180 y 180.'
      }
    }];
  }

  return [{
    json: {
      ...i,
      location_input_type: 'coords',
      lat_validada: lat,
      lon_validada: lon,
      coords_validas: true,
      caseId: i.caseId || i.pending_case_id,
      tipo: i.pending_type || 'INCENDIO',
      prioridad: i.pending_priority || 'MEDIA'
    }
  }];
}

// FIX (nueva funcionalidad): si no son coordenadas ni ubicacion nativa,
// tratamos el texto como nombre de lugar/camino/monte y lo geocodificamos
// por texto en el siguiente nodo (Geocoding por texto).
if (texto.length === 0) {
  return [{
    json: {
      ...i,
      location_input_type: 'invalid',
      coords_validas: false,
      whatsappTo: String(i.from || '').replace(/\D/g, ''),
      whatsappText: 'No he podido leer tu mensaje. Puedes enviarme tu ubicación de WhatsApp, el nombre del lugar/camino/monte, o coordenadas en formato: 40.4168, -3.7038'
    }
  }];
}

return [{
  json: {
    ...i,
    location_input_type: 'text',
    ubicacion_texto: texto,
    coords_validas: false,
    caseId: i.caseId || i.pending_case_id,
    tipo: i.pending_type || 'INCENDIO',
    prioridad: i.pending_priority || 'MEDIA'
  }
}];

const i = $input.first().json;

const caseId =
  i.pending_state?.pending_case_id ||
  i.caseId ||
  i.pending_case_id ||
  null;

if (!caseId) {
  throw new Error('No se encontró caseId para actualizar el caso pendiente.');
}

const lat = i.lat_validada;
const lon = i.lon_validada;

if (lat === null || lat === undefined || lon === null || lon === undefined) {
  throw new Error('No hay coordenadas válidas para actualizar el caso.');
}

const query = `
UPDATE forest_incidents
SET
  latitude = ${lat},
  longitude = ${lon},
  location = ST_SetSRID(ST_MakePoint(${lon}, ${lat}), 4326),
  status = 'ABIERTO',
  metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
    'coordenadas_actualizadas_en', NOW(),
    'coordenadas_fuente', 'usuario_whatsapp'
  )
WHERE case_id = '${caseId}';
`;

return [{
  json: {
    ...i,
    caseId,
    updateQuery: query
  }
}];

const i = $('Extraer Coordenadas Pendientes').first().json;
const geoResponse = $input.first().json;

let ubicacionNombre = null;
let ubicacionCompleta = null;
let municipio = null;
let provincia = null;
let lat = null;
let lon = null;
let locationFound = false;

if (geoResponse.status === "OK" && geoResponse.results && geoResponse.results.length > 0) {
  const firstResult = geoResponse.results[0];

  ubicacionCompleta = firstResult.formatted_address;
  lat = firstResult.geometry?.location?.lat ?? null;
  lon = firstResult.geometry?.location?.lng ?? null;
  locationFound = lat !== null && lon !== null;

  for (const component of firstResult.address_components || []) {
    if (component.types.includes("locality")) {
      municipio = component.long_name;
    }
    if (component.types.includes("administrative_area_level_1")) {
      provincia = component.long_name;
    }
  }

  if (municipio) {
    ubicacionNombre = municipio;
  } else if (provincia) {
    ubicacionNombre = provincia;
  } else {
    ubicacionNombre = ubicacionCompleta?.split(',')[0] || 'Ubicación detectada';
  }

  if (i.parcela) {
    ubicacionNombre = `Parcela ${i.parcela} (${municipio || provincia || 'Ubicación detectada'})`;
  }

} else {
  ubicacionNombre = i.ubicacion_texto || 'Ubicación no encontrada';
  ubicacionCompleta = null;
}

return [{
  json: {
    ...i,

    location_found: locationFound,
    coords_validas: locationFound,

    lat_validada: lat,
    lon_validada: lon,

    ubicacion_nombre: ubicacionNombre,
