  }
}];

const i = $input.first().json;

const message =
  i.finalMessage ||
  i.classification?.respuesta_usuario ||
  'Puedo ayudarte a reportar humo, fuego o una posible situación de riesgo de incendio forestal.';

return [{
  json: {
    ...i,
    whatsappTo: String(i.from || '').replace(/\D/g, ''),
    whatsappText: message,
    finalMessage: message,
    userMessage: message
  }
}];

// Si ya fue procesado por la rama legal, salir
if ($input.first().json.procesado_legal === true) {
  return [];
}

const input = $input.first().json;
const original = $('Rate Limiter').first().json;

const text = input.candidates?.[0]?.content?.parts?.[0]?.text || '';

const FIRE_WORDS = /\b(humo|fuego|incendio|llamas?|arde|ardiendo|quemad[oa]|quemando|conato|chispas?|rayo|colilla|fogata|barbacoa)\b/i;

let data = null;
let aiFallback = false;
try {
  if (!text) throw new Error('Respuesta vacía de Gemini');
  const clean = text.replace(/```json/gi, '').replace(/```/g, '').trim();
  const match = clean.match(/\{[\s\S]*\}/);
  data = JSON.parse(match ? match[0] : clean);
} catch (e) {
  aiFallback = true;
}

// FIX v2.1: si la IA falla, no perder avisos de incendio.
// Con palabras de fuego -> caso INCENDIO MEDIA con escalado; sin ellas -> pedir detalle.
if (aiFallback) {
  const pareceIncendio = FIRE_WORDS.test(String(original.message || ''));
  data = pareceIncendio
    ? {
        tipo: 'INCENDIO',
        subtipo: null,
        prioridad: 'MEDIA',
        crear_caso: true,
        descripcion: `[Clasificado sin IA] ${original.message}`,
        coordenadas: { lat: original.latitude, lon: original.longitude },
        requiere_escalado: true,
        respuesta_usuario: 'He registrado tu aviso de posible incendio.'
      }
    : {
        tipo: 'OTRO',
        prioridad: 'BAJA',
        crear_caso: false,
        descripcion: original.message,
        coordenadas: { lat: original.latitude, lon: original.longitude },
        requiere_escalado: false,
        respuesta_usuario: 'Ahora mismo no he podido procesar tu mensaje. Si estás viendo humo o fuego, escríbeme qué ocurre. Si hay peligro inmediato, llama al 112.'
      };
}

const tiposValidos = ['INCENDIO', 'OTRO'];
if (!tiposValidos.includes(data.tipo)) {
  data.tipo = 'OTRO';
}
if (!['ALTA', 'MEDIA', 'BAJA'].includes(data.prioridad)) {
  data.prioridad = 'MEDIA';
}

// Si WhatsApp recibió ubicación nativa, tiene prioridad sobre Gemini
if (original.latitude !== null && original.longitude !== null) {
  data.coordenadas = {
    lat: original.latitude,
    lon: original.longitude
  };
}

const lat = data.coordenadas?.lat ?? null;
const lon = data.coordenadas?.lon ?? null;

// Crear caso
let crearCaso = data.crear_caso !== false;

// FIX: declarar finalMessage AQUI, antes de cualquier uso, para evitar
// "Cannot access 'finalMessage' before initialization"
let finalMessage =
  data.respuesta_usuario ||
  'He registrado tu mensaje.';

// Seguridad extra: saludos/casuales no crean caso aunque Gemini falle
const mensajeLimpio = String(original.message || '').trim().toLowerCase();
const soloCoordenadas =
  /^-?\d+(\.\d+)?\s*,\s*-?\d+(\.\d+)?$/.test(mensajeLimpio);

if (soloCoordenadas && original.has_pending !== true) {
  crearCaso = false;
  data.tipo = 'OTRO';
  data.prioridad = 'BAJA';
  data.requiere_escalado = false;
  finalMessage = 'He recibido unas coordenadas, pero no tengo ningún aviso pendiente asociado. Para reportar un incendio, escribe primero qué está ocurriendo: humo, fuego, olor a quemado o riesgo de incendio.';
}

const mensajesCasuales = [
  'hola', 'buenas', 'buenos dias', 'buenos días',
  'buenas tardes', 'buenas noches', 'gracias',
  'ok', 'vale', 'perfecto', 'adios', 'adiós'
];

const mensajeSinPuntuacion = mensajeLimpio.replace(/[¡!¿?.,;:)(]/g, '').replace(/\s+/g, ' ').trim();

if (mensajesCasuales.includes(mensajeSinPuntuacion)) {
  data.tipo = 'OTRO';
  crearCaso = false;
  data.prioridad = 'BAJA';
  data.requiere_foto = false;
  data.requiere_coordenadas = false;
  data.requiere_escalado = false;
}

// Coordenadas necesarias
const needsCoords =
  crearCaso === true &&
  ['INCENDIO'].includes(data.tipo) &&
  (lat === null || lon === null);

const requiereEscalado =
  crearCaso === true &&
  (
    data.requiere_escalado === true ||
    data.prioridad === 'ALTA'
  );

if (needsCoords) {
  finalMessage = `He clasificado tu aviso como *${data.tipo}*.

Para registrarlo correctamente necesito la ubicación exacta. Puedes enviarme la ubicación de WhatsApp o escribir las coordenadas en formato: 40.4168, -3.7038`;
}

return [{
  json: {
    ...original,
    classification: data,
    ai_fallback: aiFallback,
    tipo: data.tipo,
    prioridad: data.prioridad,
    crearCaso,
    descripcion: data.descripcion || original.message,
    lat,
    lon,
    ubicacion_texto: data.ubicacion_texto || null,
    parcela: data.parcela || null,
    necesita_coordenadas: needsCoords,
    requiereEscalado,
    finalMessage,
    caseId: crearCaso
      ? `FOR-${Date.now()}-${Math.random().toString(36).slice(2, 7).toUpperCase()}`
      : null
  }
}];

const i = $input.first().json;

// Función para validar coordenadas
function validarCoordenadas(lat, lon) {
  const latNum = parseFloat(lat);
  const lonNum = parseFloat(lon);

  if (Number.isNaN(latNum) || Number.isNaN(lonNum)) {
    return {
      valida: false,
      lat: null,
      lon: null,
      error: 'No son números'
    };
  }

  if (Math.abs(latNum) > 90) {
    return {
      valida: false,
      lat: null,
      lon: null,
      error: 'Latitud fuera de rango (-90 a 90)'
    };
  }

  if (Math.abs(lonNum) > 180) {
    return {
      valida: false,
      lat: null,
      lon: null,
      error: 'Longitud fuera de rango (-180 a 180)'
    };
  }

  return {
    valida: true,
    lat: latNum,
    lon: lonNum,
    error: null
  };
}

// Obtener coordenadas de diferentes fuentes
let lat =
  i.lat ??
  i.coordenadas?.lat ??
  i.classification?.coordenadas?.lat ??
  null;

let lon =
  i.lon ??
  i.coordenadas?.lon ??
  i.classification?.coordenadas?.lon ??
  null;

// Si no hay coordenadas en el objeto principal, buscar en metadata
if ((lat === null || lon === null) && i.metadata) {
  lat = lat ?? i.metadata.coordenadas_lat ?? null;
  lon = lon ?? i.metadata.coordenadas_lon ?? null;
}

const coords = validarCoordenadas(lat, lon);

// En esta versión simplificada, solo INCENDIO requiere coordenadas
const necesitaCoordenadas =
  i.tipo === 'INCENDIO' &&
  !coords.valida;

// Mensaje para pedir coordenadas si es necesario
let mensajePedirCoordenadas = '';

if (necesitaCoordenadas) {
  mensajePedirCoordenadas = `Para registrar correctamente el aviso de incendio, necesito la ubicación exacta.

Puedes enviarme:
• Tu ubicación de WhatsApp
• Coordenadas (ej: 40.4168, -3.7038)
• Nombre del monte, paraje o zona`;
}

return [
  {
    json: {
      ...i,

      lat_validada: coords.lat,
      lon_validada: coords.lon,
      coords_validas: coords.valida,
      error_coordenadas: coords.error,

      necesita_coordenadas: necesitaCoordenadas,
      mensaje_pedir_coordenadas: mensajePedirCoordenadas
    }
  }
];

const i = $input.first().json;

const tipo =
  i.tipo ||
  i.pending_type ||
  i.pending_state?.pending_type ||
  'OTRO';

const prioridad =
  i.prioridad ||
  i.pending_priority ||
  (tipo === 'INCENDIO' ? 'ALTA' : 'MEDIA');

const shouldNotifySupervisor =
  tipo === 'INCENDIO' ||
  prioridad === 'ALTA';

const supervisorNumber =
  $env.SUPERVISOR_WHATSAPP || '';

const ubicacion =
  i.ubicacion_nombre ||
  i.ubicacion_completa ||
  `${i.lat_validada}, ${i.lon_validada}`;

const supervisorMessage = `🔥 *WILDFIRE SENTINEL AI*
━━━━━━━━━━━━━━━━━━━━
📌 *CASO ACTUALIZADO*
━━━━━━━━━━━━━━━━━━━━
🔹 *Tipo:* ${tipo}
🔹 *Prioridad:* ${prioridad}
🔹 *ID:* ${i.caseId}
🔹 *Ubicación:* ${ubicacion}
🔹 *Coordenadas:* ${i.lat_validada}, ${i.lon_validada}
🔹 *Reporta:* ${i.userName || 'Usuario'}
🔹 *Teléfono:* ${i.from}
━━━━━━━━━━━━━━━━━━━━
⚠️ El usuario ha enviado la ubicación pendiente.`;

return [{
  json: {
    ...i,
    supervisorNumber,
