const original = $('Preparar Imagen Base64').first().json;
const input = $input.first().json;

const text = input.candidates?.[0]?.content?.parts?.[0]?.text || '';

let vision = null;
try {
  if (!text) throw new Error('Respuesta vacía de Gemini Vision');
  const clean = text.replace(/```json/gi, '').replace(/```/g, '').trim();
  const match = clean.match(/\{[\s\S]*\}/);
  vision = JSON.parse(match ? match[0] : clean);
} catch (e) {
  vision = null;
}

const visionFallback = vision === null;
const v = vision || {};

const hayFuego = v.hay_fuego === true;
const hayHumo = v.hay_humo === true;
const viviendasCerca = v.hay_viviendas_cerca === true;
const incendioGrande = v.tamano_incendio === 'GRANDE';

// FIX v2.1: si Vision dice claramente que no hay fuego ni humo, no se crea caso.
// Si Vision falla, se trata como posible incendio (opción segura).
const noEsIncendio =
  !visionFallback &&
  v.es_incendio_forestal_probable === false &&
  !hayFuego &&
  !hayHumo;

if (noEsIncendio) {
  const msg = 'He analizado la imagen, pero no veo humo ni fuego. Si estás viendo un incendio, escríbeme qué ocurre o envíame otra foto. Si hay peligro inmediato, llama al 112.';
  return [{
    json: {
      ...original,
      vision_result: v,
      vision_fallback: false,
      tipo: 'OTRO',
      prioridad: 'BAJA',
      crearCaso: false,
      caseId: null,
      requiereEscalado: false,
      finalMessage: msg,
      userMessage: msg,
      classification: { tipo: 'OTRO', prioridad: 'BAJA', crear_caso: false, respuesta_usuario: msg }
    }
  }];
}

const prioridad =
  v.prioridad === 'ALTA' || hayFuego || viviendasCerca || incendioGrande
    ? 'ALTA'
    : 'MEDIA';

const requiereEscalado = prioridad === 'ALTA' || v.requiere_escalado === true || visionFallback;

const descripcion =
  (visionFallback ? '[Imagen sin analizar] ' : '') +
  (v.descripcion || original.caption || 'Imagen recibida con posible humo o incendio forestal.');

const tieneUbicacion = original.latitude !== null && original.longitude !== null;

const caseId =
  `FOR-${Date.now()}-${Math.random().toString(36).slice(2, 7).toUpperCase()}`;

return [{
  json: {
    ...original,

    vision_result: v,
    vision_fallback: visionFallback,

    classification: {
      tipo: 'INCENDIO',
      subtipo: hayFuego ? 'FUEGO' : hayHumo ? 'HUMO' : 'OTRO_RIESGO',
      prioridad,
      crear_caso: true,
      descripcion,
      coordenadas: { lat: original.latitude, lon: original.longitude },
      ubicacion_texto: v.ubicacion_texto || original.caption || null,
      requiere_coordenadas: !tieneUbicacion,
      requiere_escalado: requiereEscalado,
      respuesta_usuario: 'He recibido la imagen del posible incendio.'
    },

    tipo: 'INCENDIO',
    prioridad,
    crearCaso: true,
    descripcion,

    lat: original.latitude,
    lon: original.longitude,

    ubicacion_texto: v.ubicacion_texto || original.caption || null,
    parcela: null,

    necesita_coordenadas: !tieneUbicacion,
    requiereEscalado,

    finalMessage: tieneUbicacion
      ? 'He recibido la imagen y la ubicación del posible incendio.'
      : `🔥 *Aviso de incendio forestal*

He recibido la imagen y la he analizado como posible incendio.

Para registrarlo correctamente necesito la ubicación exacta.

Puedes enviarme:

📍 Tu ubicación de WhatsApp
🗺️ Nombre del monte, camino o zona
🌍 Coordenadas aproximadas`,

    caseId
  }
}];

const i = $input.first().json;
const text = String(i.message || '').trim().toLowerCase();

const esUbicacionWhatsApp =
  i.latitude !== null && i.latitude !== undefined &&
  i.longitude !== null && i.longitude !== undefined;

const pareceCoordenadas =
  /^-?\d+(\.\d+)?\s*,\s*-?\d+(\.\d+)?$/.test(text);

const tienePalabrasIncendio =
  /\b(humo|fuego|incendio|llamas|arde|ardiendo|quemado|quemando|conato|explosión|explosion|chispa|chispas|barbacoa|fogata|rayo|colilla|olor a quemado|huele a quemado)\b/.test(text);

// FIX v2.1: respuestas casuales no se tratan como nombre de lugar
const textoSinPuntuacion = text.replace(/[¡!¿?.,;:)(]/g, '').replace(/\s+/g, ' ').trim();
const MENSAJES_CASUALES = [
  'hola', 'buenas', 'buenos dias', 'buenos días', 'buenas tardes', 'buenas noches',
  'gracias', 'muchas gracias', 'vale', 'vale gracias', 'ok', 'okay', 'ok gracias',
  'perfecto', 'genial', 'de acuerdo', 'entendido', 'si', 'sí', 'no', 'adios', 'adiós'
];
const esCasual = MENSAJES_CASUALES.includes(textoSinPuntuacion);

const pareceLugarTexto =
  !i.isImage &&
  !esCasual &&
  !tienePalabrasIncendio &&
  !pareceCoordenadas &&
  textoSinPuntuacion.length >= 3;

return [{
  json: {
    ...i,
    pending_reply_type:
      esUbicacionWhatsApp || pareceCoordenadas
        ? 'coords'
        : pareceLugarTexto
          ? 'place_text'
          : 'new_report'
  }
}];

const original = $('Construir SQL Actualizar Caso').first().json;
const pgResult = $input.first().json;

return [{
  json: {
    ...original,
    postgres_update_result: pgResult
  }
}];

const original = $('Parsear WhatsApp').first().json;

const item = $input.first();
const binary = item.binary || {};
const binaryKey = Object.keys(binary)[0];

if (!binaryKey) {
  throw new Error('No se encontró imagen binaria descargada.');
}

const imageInfo = binary[binaryKey];

const buffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);
const base64 = buffer.toString('base64');

return [{
  json: {
    ...original,
    image_base64: base64,
    image_mime_type: imageInfo.mimeType || 'image/jpeg'
  }
}];

const i = $input.first().json;

// FIX v2.1: una foto mientras se espera la ubicación no abre un caso nuevo.
const msg = `📍 Todavía necesito la ubicación de tu aviso anterior${i.pending_case_id ? ` (ID: ${i.pending_case_id})` : ''}.

Puedes enviarme:

📍 Tu ubicación de WhatsApp
🌍 Coordenadas (ej: 40.4168, -3.7038)
🗺️ Nombre del monte, paraje o zona`;

return [{
  json: {
    ...i,
    whatsappTo: String(i.from || '').replace(/\D/g, ''),
    whatsappText: msg,
    finalMessage: msg
  }
}];
